/** Pixel typography only: font sizes, weights, colors, and syntax tokens stay owned by existing styles. */
window.__ModuleLoader__.load({id:'dsh-pixel-font',factory:()=>({name:'pixel-font-client',apply(ctx){ctx.effect(()=>{const style=document.createElement('style');style.id='pg-pixel-font';style.textContent="@font-face{font-family:'PureGamma Pixel';src:url('data:font/woff2;base64,') format('woff2');font-style:normal;font-display:swap;}body,body *:not(svg):not(svg *):not(.katex):not(.katex *){font-family:'PureGamma Pixel',monospace !important;}body{--dsh-font-family-text:'PureGamma Pixel',monospace !important;--dsh-font-family-code:'PureGamma Pixel',monospace !important;}";document.head.append(style);return()=>style.remove();},'pg-pixel-font');}})});
